1583	 *
1584	 * `superseded_by` accepts `null` to allow callers to explicitly clear the field.
1585	 * The handler maps `null → undefined` before forwarding to `updateInsight()`.
1586	 */
1587	export const KnowledgeUpdateBodySchema = z
