1605	/**
1606	 * Parses a raw string as a positive integer insight ID.
1607	 *
1608	 * Rejects:
1609	 * - Non-numeric strings (NaN after Number())
1610	 * - Floating-point strings (any string containing '.', e.g. "1.5", "2.0")
1611	 * - Zero or negative integers
1612	 *
1613	 * The decimal-point check is performed on the raw string before numeric
1614	 * coercion so that "2.0" (which coerces to an integer) is still rejected.
1615	 *
1616	 * @throws ApiError VALIDATION_ERROR for any rejected value.
1617	 */
1618	function parseKnowledgeId(raw: string): number {
1619	  // Reject strings containing a decimal point before numeric coercion —
1620	  // this catches "1.5" and also "2.0", both of which the caller must treat
1621	  // as non-integer IDs even though Number("2.0") === 2.
1622	  if (raw.includes('.')) {
1623	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
1624	  }
1625	  const n = Number(raw);
1626	  if (!Number.isInteger(n) || n <= 0) {
1627	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
1628	  }
1629	  return n;
1630	}
1631	
1632	/**
1633	 * Locates an insight by numeric ID within the manager's stores.
1634	 *
1635	 * Calls `manager.listInsights(filter ?? {})` to retrieve the candidate set,
1636	 * then finds the first insight with a matching `.id`.
1637	 *
1638	 * @param manager  KnowledgeStoreManager instance
1639	 * @param id       Numeric insight ID
1640	 * @param filter   Optional scope/project_slug/category filter passed to listInsights
1641	 * @throws ApiError NOT_FOUND when no matching insight exists
1642	 */
1643	async function findInsightById(
1644	  manager: KnowledgeStoreManager,
1645	  id: number,
1646	  filter?: Parameters<KnowledgeStoreManager['listInsights']>[0]
1647	): Promise<Insight> {
1648	  const insights = await manager.listInsights(filter ?? {});
1649	  const found = insights.find((i) => i.id === id);
1650	  if (!found) {
1651	    throw new ApiError('NOT_FOUND', 'Insight not found.');
1652	  }
1653	  return found;
1654	}
